"use client";

import { FormEvent, useEffect, useState } from "react";
import "./styles.css";
import GamesPanel from "./GamesPanel";

type State = { character: { name: string; growthStage: string; experience: number; status: { hunger: number; energy: number; friendship: number }; messages: Array<{ id: string; role: string; content: string }> } };
type Analysis = { personalityType: string; topics: Array<{ topic: string; count: number }> };
const actions = [{ id: "feed", label: "ごはん", icon: "🍙" }, { id: "play", label: "遊ぶ", icon: "🎮" }, { id: "sleep", label: "寝かせる", icon: "💤" }];

export default function Home() {
  const [auth, setAuth] = useState<"login" | "register">("login");
  const [email, setEmail] = useState(""); const [password, setPassword] = useState("");
  const [state, setState] = useState<State | null>(null); const [error, setError] = useState("");
  const [message, setMessage] = useState(""); const [sending, setSending] = useState(false);
  const [gameResult, setGameResult] = useState("");
  const [analysis, setAnalysis] = useState<Analysis | null>(null);
  const load = async () => { const response = await fetch("/api/state"); if (response.ok) setState(await response.json()); };
  useEffect(() => { void load(); }, []);
  async function submitAuth(event: FormEvent) { event.preventDefault(); setError(""); const response = await fetch(`/api/auth/${auth}`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ email, password }) }); const data = await response.json(); if (!response.ok) setError(data.error); else await load(); }
  async function care(action: string) { const response = await fetch("/api/care", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action }) }); if (response.ok) await load(); }
  async function chat(event: FormEvent) { event.preventDefault(); if (!message.trim()) return; setSending(true); const response = await fetch("/api/chat", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ message }) }); const data = await response.json(); if (!response.ok) setError(data.error); else { setMessage(""); await load(); } setSending(false); }
  async function playRps(choice: string) { const response = await fetch("/api/game", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ choice }) }); const data = await response.json(); if (!response.ok) setError(data.error); else { setGameResult(`相手は${data.opponent}。${data.result === "win" ? "あなたの勝ち！" : data.result === "lose" ? "あなたの負け…" : "引き分け！"}`); await load(); } }
  async function analyze() { const response = await fetch("/api/analysis"); const data = await response.json(); if (!response.ok) setError(data.error); else setAnalysis(data); }
  async function resetCharacter() { if (!window.confirm("育成データと会話履歴をすべて初期化しますか？")) return; const response = await fetch("/api/character/reset", { method: "POST" }); if (response.ok) { setAnalysis(null); await load(); } }
  if (!state?.character) return <main className="auth"><section className="card"><p className="eyebrow">AI ごっち</p><h1>あなただけの相棒を育てよう</h1><p>話しかけたり、お世話をしたりしてキャラクターを育てます。</p><form onSubmit={submitAuth}><label>メールアドレス<input type="email" value={email} onChange={e => setEmail(e.target.value)} required /></label><label>パスワード<input type="password" value={password} onChange={e => setPassword(e.target.value)} minLength={8} required /></label>{error && <p className="error">{error}</p>}<button>{auth === "login" ? "ログイン" : "アカウントを作成"}</button></form><button className="link" onClick={() => setAuth(auth === "login" ? "register" : "login")}>{auth === "login" ? "初めての方はこちら" : "ログインに戻る"}</button></section></main>;
  const character = state.character;
  return <main className="dashboard"><header><div><p className="eyebrow">AI ごっち</p><h1>{character.name}のお部屋</h1></div><button className="secondary" onClick={async () => { await fetch("/api/auth/logout", { method: "POST" }); setState(null); }}>ログアウト</button></header><section className="pet card"><div className="pet-face">{character.growthStage === "たまご" ? "🥚" : character.growthStage === "こども" ? "🐣" : "🐥"}</div><div><span className="badge">{character.growthStage}</span><h2>こんにちは！</h2><p>経験値 {character.experience} / 300</p></div></section><section className="stats card">{[["おなか", character.status.hunger], ["元気", character.status.energy], ["なかよし度", character.status.friendship]].map(([label, value]) => <div key={label as string}><span>{label}</span><strong>{value}%</strong><progress max="100" value={value as number} /></div>)}</section><section className="care card"><h2>お世話する</h2><div className="actions">{actions.map(item => <button key={item.id} onClick={() => care(item.id)}><span>{item.icon}</span>{item.label}</button>)}</div></section><section className="care card"><h2>じゃんけん</h2><div className="actions">{[["rock", "グー"], ["paper", "パー"], ["scissors", "チョキ"]].map(([value, label]) => <button key={value} onClick={() => playRps(value)}>{label}</button>)}</div>{gameResult && <p>{gameResult}</p>}</section><GamesPanel /><section className="chat card"><h2>おはなし</h2><div className="messages">{[...character.messages].reverse().map(item => <p className={item.role} key={item.id}>{item.content}</p>)}</div><form onSubmit={chat}><input value={message} onChange={e => setMessage(e.target.value)} placeholder="今日の出来事を話してみよう" /><button disabled={sending}>送る</button></form>{error && <p className="error">{error}</p>}</section><section className="settings card"><h2>キャラクター分析・設定</h2><div className="actions"><button className="secondary" onClick={() => void analyze()}>性格・話題を分析</button><button className="secondary" onClick={() => void resetCharacter()}>育成をやり直す</button></div>{analysis && <p>性格タイプ: <strong>{analysis.personalityType}</strong><br />話題: {analysis.topics.length ? analysis.topics.map((topic) => `${topic.topic} (${topic.count})`).join("、") : "まだ十分な会話がありません"}</p>}<p className="terms">会話内容はキャラクター育成と分析のために保存されます。</p></section></main>;
}
